            scenarios=(m.EstimateScenario(scenario_id="offline:nominal", estimate_ids=tuple(e.estimate_id for e in estimates)),)
            if enabled else (), robust_rule="worst_total", unavailable_rule="block_relationship_sensitive",
            issues=(),
        )
        economic = m.EconomicContext(case=inputs.case, standards_by_supplier=tuple(standards), estimates=tuple(estimates),
                                     scenario_policy=policy, cost_policy=inputs.cost_policy, fingerprint="0" * 64, issues=())
        economic = economic.model_copy(update={"fingerprint": economic_fingerprint(economic)})
        ref = m.SnapshotRef(run_id=inputs.state.run_id, session_id=inputs.server.session_id,
                            state_version=inputs.state.version, context_version=evidence.context_version,
                            config_hash=inputs.state.config_hash, case_contract_hash=inputs.case.contract_hash)
