                                       capabilities=("used-action-v1", "offline-declared-inputs-v1"), as_of=inputs.as_of)
        thread = next((t for t in inputs.server.threads if t.supplier_id == inputs.target_supplier_id), None)
        if thread is None:
            raise ContractViolation("scope_mismatch: target has no identified conversation")
        return m.DecisionSnapshot(context=context, state=inputs.state, target_supplier_id=inputs.target_supplier_id,
                                   conversation=thread.conversation, budget=inputs.budget)
